/* Темы раздела «Обучение»: что показать курсором и как это объяснить новому администратору. Движок — assets/tour.js.
   Глава — одна задача, начинается шагом с ch:{title, why}; последний шаг главы лучше делать без act: на нём показ останавливается.
   Подписи — о том, что делает функция и зачем она нужна. Никаких «раньше было»: человек видит продукт впервые.
   ID темы и главы (ch.id) — латиницей, [a-z][a-z0-9-]*, навсегда: по ним ссылаются адрес показа, каталог (Tour.catalog) и ассистент
   (answer.learn). Перестановка, переименование и новая соседняя глава ID не меняют; ID удалённой главы другой главе не дают. */
const tourQ = (sel) => () => document.querySelector(sel);
const tourText = (sel, re) => () => [...document.querySelectorAll(sel)].find((e) => re.test(e.textContent));

Tour.add({
  id: "tree",
  title: "Как найти объект в дереве",
  why: "В системе могут быть тысячи объектов. Срезы, папки и статус быстро сужают дерево до нужного.",
  steps: (() => {
    const q = tourQ;
    // Цель появляется, только когда предыдущий шаг дошёл: при перемотке шаги идут почти без пауз
    const when = (cond, at) => () => (cond() ? at() : null);
    const sw = q("#viewBtn"), sliceBtn = (s) => q(`#aside [data-slice="${s}"]`), statusBtn = q("#filtBtn");
    const statusItem = (id) => q(`#filtPop.open [data-status="${id}"]`);
    const hintIn = (s, st) => when(() => slice === s && curStatus() === st && fs && fs.done && !fs.busy && /\d/.test(document.getElementById("filtHint")?.textContent || ""), q("#filtHint"));
    const svcRow = () => [...document.querySelectorAll("#tree .n[data-pick]")].find((e) => SVC_TYPES.has(find(e.dataset.pick)?.n.type));
    return [
      { ch: { id: "slices", title: "Срезы и папки", why: "Срез выбирает, какие объекты показать, а папки — как их разложить. Вместе они убирают из дерева всё лишнее." },
        say: "Кнопка «Папки» раскладывает дерево по вашей структуре: зданиям, этажам, зонам. При входе она нажата.",
        before: () => { goApp("hw"); setSlice("all"); setGroup("folder"); }, at: sw },
      { say: "Срез выбирает, какие объекты показать. Выберем «Камеры».", at: sliceBtn("cam"), act: "click" },
      { say: "Папки остались: срез решает, что показать, а раскладку меняете только вы. Выключим папки.", at: when(() => slice === "cam" && group() === "folder", sw), act: "click" },
      { say: "Дерево показывает те же объекты по серверам. Выберем другой срез.", at: when(() => group() === "server", sliceBtn("acfa")), act: "click" },
      { say: "Выбор раскладки общий для всех срезов. В «Детекторах» при выключенных папках дерево показывает виды детекторов. Включим папки снова.", at: when(() => slice === "acfa" && group() === "server", sw), act: "click" },
      { say: "В «Серверах» и «Хранилищах» папок нет.", at: when(() => group() === "folder", sliceBtn("srv")), act: "click" },
      { say: "Поэтому здесь кнопка неактивна, а подсказка объясняет почему.", at: when(() => slice === "srv" && sw()?.disabled, sw) },
      { say: "Ваш выбор сохранился. Вернёмся к «Камерам».", at: when(() => slice === "srv", sliceBtn("cam")), act: "click" },
      { say: "Папки снова включены: срезы не меняют вашу раскладку.", at: when(() => slice === "cam" && !sw()?.disabled && group() === "folder", sw) },

      { ch: { id: "status", title: "Отбор по статусу", why: "Статус показывает, что требует внимания. Так вы сразу находите, например, камеры без сигнала." },
        say: "Статус оставляет в дереве только объекты в нужном состоянии. Откроем список состояний.", at: when(() => slice === "cam", statusBtn), act: "click" },
      { say: "Оставим устройства без сигнала: их обычно проверяют первыми.", at: statusItem("nosignal"), act: "click" },
      { say: "«Найдено» считает то, что показано в этом срезе. Число всегда совпадает с деревом.", at: hintIn("cam", "nosignal") },
      { say: "Сменим срез. Статус останется, выбирать его заново не нужно.", at: when(() => curStatus() === "nosignal", sliceBtn("det")), act: "click" },
      { say: "Статус на месте, а «Найдено» пересчиталось для детекторов.", at: hintIn("det", "nosignal") },
      { say: "Снимем статус.", at: when(() => slice === "det", statusBtn), act: "click" },
      { say: "«Все статусы» возвращают полный список.", at: statusItem(""), act: "click" },
      { say: "Дерево снова показывает все объекты среза." },

      { ch: { id: "services", title: "Службы в дереве", why: "Экспорт и рассылки — тоже объекты системы. Их можно найти в дереве и открыть, как камеру." },
        say: "Службы показаны в срезе «Оборудование». Откроем его.", at: when(() => !curStatus(), sliceBtn("all")), act: "click" },
      { say: "У каждого домена есть группа «Службы»: экспорт, рассылки и другие. Откроем её.", at: when(() => slice === "all" && group() === "folder", q('#tree .n[data-tid^="svcs:"]')), act: "click" },
      { say: "Группа раскрывается, как папка, и ведёт к карточке службы. Поиск службы приводит к этой же строке.",
        before: () => document.querySelector('#tree .n[data-tid^="svcs:"]')?.scrollIntoView({ block: "start" }), at: svcRow },
      { say: "Итог: срез выбирает объекты, папки — раскладку, статус — состояние. Эти выборы не мешают друг другу, а «Найдено» совпадает с деревом." },
    ];
  })(),
});

Tour.add({
  id: "folders",
  title: "Как разложить объекты по папкам",
  why: "Папки повторяют вашу структуру: здания, этажи, зоны. Они работают как папки в Проводнике.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const row = (re) => byText("tr.fl-r", re);
    // Таблица перерисовывается: строка и её имя-ссылка ищутся заново
    const link = (re) => () => row(re)()?.querySelector(".fl-name-t");
    const folderId = (re) => { let id = null; walkFolders((f) => { if (!id && re.test(f.name)) id = f.id; }); return id; };
    return [
      { ch: { id: "list", title: "Список папок", why: "Один и тот же список работает на всех уровнях: у домена и внутри любой папки. Он устроен как Проводник." },
        say: "У домена есть вкладка «Папки»: список верхнего уровня. Такой же список открывается внутри любой папки.",
        before: () => { closeWizard(); goApp("hw"); if (treeLayout() !== "folders") toggleFolders(); pick(domains[0].id); }, at: byText(".hd .tabs .tab.on", /Папки/) },
      { say: "В строке видно, сколько в папке объектов. Щелчок только выбирает строку, как в Проводнике.", at: row(/Офис на Тверской/), act: "click" },
      { say: "Что можно сделать с выбранным, собрано над списком: открыть, переместить, добавить ещё в одну папку, убрать.", at: byText("#flBar", /Выбрано/) },
      { say: "Открывает имя-ссылка, двойной щелчок или Enter.", at: link(/Офис на Тверской/), act: "click" },
      { say: "Дерево идёт следом за правой частью: нужная строка раскрыта и подсвечена.", at: byText("#tree .n.on", /Офис на Тверской/) },

      { ch: { id: "content", title: "Что лежит в папке", why: "В одном списке сразу видны тип, адрес и состояние, поэтому неисправное устройство легко найти." },
        say: "Внутри папки один список: тип, адрес и состояние видны сразу.",
        before: () => flOpen(folderId(/Инженерные системы/)), at: () => document.querySelector(".fl-facets") && document.querySelector(".fl-tbl") },
      { say: "Фильтры оставляют только нужное. Выберем устройства без сигнала.", at: byText(".fl-facets .stchip", /Нет сигнала/), act: "click" },
      { say: "Кнопка «Вверх» возвращает на уровень выше.", at: q(".fl-up"), act: "click" },
      { say: "Папка, из которой вышли, подсвечена: сразу видно, откуда пришли.", at: byText("tr.fl-r.on", /Инженерные системы/) },
      { say: "Переключатель показывает всё, что лежит глубже, одним списком.", at: q(".fl-nested"), act: "click" },
      { say: "У каждого устройства написано, в какой оно подпапке.", at: q("td .fl-also") },

      { ch: { id: "subfolder", title: "Новая подпапка", why: "Подпапка создаётся прямо в списке, поэтому экран никуда не уходит." },
        say: "Подпапка создаётся там, где вы находитесь: строка с именем появится в этом же списке.", before: () => { if (fl.nested) flNested(false); }, at: q(".fl-add-folder"), act: "click" },
      { say: "Вводим имя. Enter создаёт папку, Esc отменяет.", before: () => { const el = document.getElementById("flDraft"); if (el) el.value = ""; }, at: q("#flDraft"), act: "type", text: "Новая зона" },
      { say: "Папка появилась в этом же списке и выбрана, а дерево обновилось.", before: () => flDraftCommit(), at: byText("tr.fl-r.on", /Новая зона/) },

      { ch: { id: "move", title: "Устройства в папку", why: "План показывает все изменения заранее: пока он не применён, в системе ничего не меняется." },
        say: "Добавление — отдельный шаг. Откроем его.", at: byText(".hd-act .btn.pri", /Добавить в папку/), act: "click" },
      { say: "Папка, куда всё попадёт, всегда на виду и меняется здесь же. Источники: найденные в сети, по адресу, из файла.", at: q(".plan-fld") },
      { say: "Ещё один источник: устройства, которые уже есть в системе. Они останутся на месте и появятся ещё и в этой папке.", at: byText("#wizDr .tab, #wizDr button", /^Уже в системе/), act: "click" },
      { say: "Отмечаем устройство. Рядом видно, где оно лежит сейчас.", at: () => byText(".fa-tbl tbody tr", /Аудитория 1/)()?.querySelector("input.ts-chk"), act: "click" },
      { say: "Сначала в план: пока план не применён, в системе ничего не меняется.", at: byText(".fa-wrap .btn.pri", /В план \(1\)/), act: "click" },
      { say: "Следующий шаг мастера: план.", at: q("#wn"), act: "click" },
      { say: "Применяем план.", at: q("#planApplyBtn:not(:disabled)"), act: "click" },
      { say: "Устройство теперь в папке, а подпись напоминает, где ещё оно лежит.", before: () => closeWizard(), at: row(/Аудитория 1/) },

      { ch: { id: "unfiled", title: "Устройства без папки", why: "Новое устройство не обязано сразу лежать в папке. Оно работает как обычно и ждёт в отдельном списке." },
        say: "На верхнем уровне последней строкой идут устройства вне папок. Они работают как обычно, просто ещё не разложены. Откроем.",
        before: () => { pick(domains[0].id); pageNo["fld:" + domains[0].id] = 2; gear(); }, at: link(/Без папки/), act: "click" },
      { say: "Это тот же список. Выбираем устройство.", at: q("tr.fl-r"), act: "click" },
      { say: "Здесь действие одно: положить в папку.", at: byText("#flBar .btn", /Положить в папку/), act: "click" },
      { say: "Выбираем папку.", at: byText("[role=menuitem]", /Входные группы/), act: "click" },
      { say: "Устройство ушло в выбранную папку. В тосте действие можно отменить." },
    ];
  })(),
});

Tour.add({
  id: "detectors",
  title: "Как настроить детекторы",
  why: "Детектор находит событие на видео, например движение или пересечение линии. Правило решает, что делать дальше.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const btn = (re) => byText("#bmodal.open button", re);
    const item = (re) => byText("#bmBody label.cp-det", re);
    const camBox = (re) => () => byText("#bmBody label.cp-row", re)()?.querySelector("input");
    const zoneRow = (re) => byText("#bmBody .dc-z-row", re);
    // Рисуем настоящими событиями мыши: обработчик зоны тот же, что у пользователя
    const drag = (a, b) => async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      let el = null;
      for (let t = 0; t < 100 && !el; t++) { el = zoneDraw && document.querySelector(`#bmodal.open svg[data-zone="${CSS.escape(zoneDraw.id)}"]`); if (!el) await wait(50); }
      if (!el) return;
      const r = el.getBoundingClientRect(), at = ([x, y]) => ({ clientX: r.left + x * r.width, clientY: r.top + y * r.height, bubbles: true });
      const cur = document.querySelector(".tour-cur");
      const go = (p) => { const o = at(p); if (cur) cur.style.transform = `translate(${o.clientX}px,${o.clientY}px)`; return o; };
      go(a); await wait(800);
      el.dispatchEvent(new MouseEvent("mousedown", at(a)));
      for (let i = 1; i <= 20; i++) { window.dispatchEvent(new MouseEvent("mousemove", go([a[0] + (b[0] - a[0]) * i / 20, a[1] + (b[1] - a[1]) * i / 20]))); await wait(35); }
      window.dispatchEvent(new MouseEvent("mouseup", at(b)));
    };
    const when = (cond, at) => () => (cond() ? at() : null);
    const CAM_NEW = "30000121-0000-4000-8000-000000000000"; // камера без детекторов
    const TRK = "30000027-0001-4000-8000-000000000000"; // трекер объектов с двумя поддетекторами
    // Окно детектора с известного места: детектор выбран, правок нет, кадр с рамками и треками, вкладка нужная
    const dwOpen = (id, ptab) => async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      closeBulkModal(); dcDrop(); goApp("hw"); await hwEnsure([id]); pick(id, { force: true });
      for (let t = 0; t < 100 && !(document.querySelector(`[data-dw="${id}"]`) && dwLoaded.has(id) && !dwBusy.has(id)); t++) await wait(50);
      if (dwChanged(find(id).n)) dwRevert(id);
      dw.lay.obj = true; dw.lay.trk = true; dw.pv = "cmp"; dw.per = 15; dw.tsp = 1; delete dw.ap[id];
      dwPtabSet(ptab);
    };
    // Пустое поле перед вводом: движок дописывает символы к значению
    const dwSize = (key) => () => { const i = document.querySelector(`[data-dw-size="${key}"]`); if (i) i.value = ""; };
    const dwFoot = () => document.querySelector("#cardFoot:not([hidden])");
    const dwStep = (n, at) => when(() => dc && dc.step === n, at);
    return [
      { ch: { id: "table", title: "Таблица детекторов", why: "Все детекторы системы собраны в одной таблице. Вы видите их вид, камеру и место работы, не открывая каждую камеру." },
        say: "Срез «Детекторы» показывает все детекторы системы одной таблицей.",
        before: () => { dcDrop(); closeBulkModal(); goApp("hw"); setSlice("det"); setGroup("kind"); detKindPick(null); }, at: q("#main .dl-tbl") },
      { say: "Кнопка среза показывает, сколько детекторов в системе.", at: q('[data-slice="det"]') },
      { say: "В дереве — виды детекторов, под видом — камеры. Имя детектора показано только там, где камера повторяется.", at: byText("#tree .n.srv", /Все детекторы/) },
      { say: "Чипы над таблицей — фильтр со счётчиком. Второй щелчок снимает чип. Оставим только встроенные детекторы.", at: byText("#main .stchip", /Встроенн/), act: "click" },
      { say: "«Встроенный» работает на самой камере, «Серверный» — на сервере. Каждая колонка сортируется.", at: byText("#main .dl-tbl th", /Размещение/), act: "click" },
      { say: "Камера в строке открывает детектор этой строки. Срез и дерево остаются теми же.", at: () => document.querySelector("#main .dl-tbl tbody tr td:nth-child(4) .dl-link"), act: "click" },
      { say: "Назад — одной ссылкой, к тому же списку.", at: q("#main .dl-back"), act: "click" },
      { say: "Вы снова в таблице, фильтр на месте.", at: q("#main .dl-tbl") },

      { ch: { id: "kinds", title: "Виды и камеры", why: "Один мастер создаёт детекторы сразу на многих камерах. Заходить в каждую камеру не нужно." },
        say: "Создать детекторы можно прямо из шапки среза.", before: () => detFacetClear(), at: byText("#main .hd button", /Добавить детекторы/), act: "click" },
      { say: "Мастер идёт по шагам. На сервер ничего не уходит до «Создать». Серверные виды подойдут любой камере, встроенные — только тем, что их умеют.", at: item(/^Движение/), act: "click" },
      { say: "Можно выбрать несколько видов сразу.", at: item(/^Пересечение линии/), act: "click" },
      { say: "Дальше — камеры.", at: btn(/^Далее$/), act: "click" },
      { say: "Камеры фильтруются так же, как таблица. Что не подойдёт, видно сразу и с причиной.", at: q("#bmBody .cp-note") },
      { say: "Выбираем камеру.", at: camBox(/Ангар — ворота/), act: "click" },
      { say: "Вторая камера: это ещё по одному детектору каждого вида.", at: camBox(/Аудитория 1/), act: "click" },
      { say: "Камеры выбраны. На следующем шаге мастер спросит про зоны." },

      { ch: { id: "zones", title: "Зоны на кадре", why: "Зона говорит детектору, где смотреть. Так он не реагирует на лишнее движение в кадре." },
        say: "Следующий шаг — зоны.", at: btn(/^Далее$/), act: "click" },
      { say: "Зоны рисуются прямо в мастере, на кадре камеры. Слева видно, у кого детектору линии ещё нужна линия.", at: zoneRow(/нет линии/) },
      { say: "Рисовать можно сразу: форма уже выбрана. Детектору линии — линия.", before: drag([.15, .65], [.85, .35]), at: q("#bmBody svg[data-zone]") },
      { say: "Один щелчок применяет зону к остальным детекторам той же формы. Зоны, нарисованные рукой, он не заменяет.", at: btn(/Такую же остальным/), act: "click" },
      { say: "Камера с готовой зоной получает галочку. У копии галочка контурная и слово «копия». Мастер сам перешёл к детекторам другой формы. Им — прямоугольник.", before: drag([.2, .25], [.7, .8]), at: zoneRow(/копия/) },
      { say: "Применяем к остальным.", at: btn(/Такую же остальным/), act: "click" },
      { say: "Строк без зоны не осталось, поэтому мастер сам идёт к правилу." },

      { ch: { id: "rule", title: "Правило", why: "Правило решает, что делать при срабатывании: записывать видео, поднять тревогу или и то и другое." },
        say: "Окно само меняет размер под шаг. «Если» заполнено выбранными детекторами. Правил будет по одному на вид.", at: byText("#bmBody .dc-sec", /^Если$/) },
      { say: "Правило — один выбор. По умолчанию запись с камеры события. Длительность и архив — здесь же.", at: q('#bmBody select[aria-label*="Архив"]') },
      { say: "Тревога добавляется к записи: камера пишет, а оператор видит тревогу.", at: byText("#bmBody .rl-opt", /Записывать и поднять тревогу/), act: "click" },
      { say: "Условия и другие действия открываются на этом же шаге. Окно плавно растёт.", at: q("#bmBody .dc-more"), act: "click" },
      { say: "Это полная форма, как в карточке правила: «Если», «При условии», «То». Она правит то же правило. Вернёмся к простому виду.", at: q("#bmBody .dc-more"), act: "click" },
      { say: "Правило готово. Осталось проверить план и создать детекторы." },

      { ch: { id: "draft", title: "Черновик и создание", why: "Незаконченная работа не теряется, даже если вас отвлекли. План показывает всё, что произойдёт, до создания." },
        say: "Окно можно закрыть, даже случайно. Выбранное, зоны и правило не пропадут.",
        before: () => { const a = arch.find((x) => archRowOk(x)); if (a) setActionField("0", "archive", a.id); }, at: q('#bmodal.open .dc-x[aria-label="Закрыть"]'), act: "click" },
      { say: "Черновик виден внизу справа в любом разделе. Можно пойти в другой раздел и вернуться.", before: () => goApp("rules"), at: q("#dcDock") },
      { say: "«Продолжить» возвращает на тот же шаг. Черновик удаляет только «Отмена» с подтверждением.", at: q("#dcDock .btn.pri"), act: "click" },
      { say: "Вернулись в «Оборудование», на шаг «Правило». Архив и зоны на месте.", at: btn(/^Далее$/), act: "click" },
      { say: "Последний шаг и есть план: камера, детектор, зона, копии, правила. Здесь видно всё, что произойдёт.", at: q("#bmBody .bk-table") },
      { say: "Детекторы создаются одной групповой операцией. Зона уходит сразу при создании. Правила создаются вместе с ними.", at: btn(/^Создать \d/), act: "click" },
      { say: "Новые детекторы в таблице уже с зонами, а правила — в «Автоматизации».", at: byText("#main .dl-tbl tbody tr", /Ангар — ворота.*Линия/) },
      { say: "Итог: всё создание, включая зоны и правило, идёт в одном мастере, и незаконченная работа не теряется." },

      { ch: { id: "window", title: "Новый детектор и его окно", why: "Окно детектора показывает на кадре, что детектор видит, рядом с его настройками. Так сразу видно, как настройка меняет результат." },
        say: "У этой камеры детекторов нет. Кнопка «Детектор» открывает мастер. Мастер уже знает эту камеру.",
        before: () => { closeBulkModal(); dcDrop(); goApp("hw"); return hwEnsure([CAM_NEW]).then(() => { pick(CAM_NEW, { force: true }); goTab("det"); }); },
        at: byText("#main .btn", /^Детектор$/), act: "click" },
      { say: "Выберем вид «Движение». Он работает на сервере, поэтому подходит любой камере.", at: item(/^Движение$/), act: "click" },
      { say: "Мы выбрали вид. Камера уже известна, поэтому мастер сразу переходит к зонам.", at: dwStep(0, btn(/^Далее$/)), act: "click" },
      { say: "Зону рисовать необязательно: без зоны детектор смотрит на весь кадр. Её можно нарисовать позже, в окне детектора.", at: dwStep(1, btn(/^Далее$/)), act: "click" },
      { say: "Мастер предлагает правило по событию. Оставим его как есть.", at: dwStep(2, btn(/^Далее$/)), act: "click" },
      { say: "Последний шаг показывает всё, что произойдёт: один детектор и одно правило.", at: dwStep(3, btn(/^Создать \d/)), act: "click" },
      { say: "Новый детектор появился в списке камеры. Откроем его.", at: byText("#main .it", /Движение/), act: "click" },
      { say: "Слева кадр с пометкой «Живое видео». Рамки показывают объекты, которые видит детектор.", at: q("#main .dw-stage") },
      { say: "Справа настройки. Вкладка «Поддетекторы» показывает поддетекторы: они решают, когда сработать. Вкладка «Автоматизация» показывает правила с этим детектором. Вкладка «Детектор» содержит разделы «Зоны детектирования», «Размер объекта» и «Условия срабатывания».", at: q("#dwRight") },
      { say: "Итог: мастер создал новый детектор, а его окно показывает настройки рядом с живым кадром." },

      { ch: { id: "subdet", title: "Поддетектор", why: "Детектор находит объекты на кадре. Поддетектор решает, когда сработать: например, когда объект долго стоит в области. На одном детекторе работает несколько поддетекторов." },
        say: "Трекер объектов только находит объекты и сам событий не создаёт. У него уже есть два поддетектора. Откроем вкладку «Поддетекторы».",
        before: dwOpen(TRK, "det"), at: q('#main [data-dw-ptab="sub"]'), act: "click" },
      { say: "У каждого поддетектора свой цвет, число сработок и переключатель «Включён». Чтобы получить новое событие, создаём ещё один поддетектор.", at: byText("#dwRight button", /Создать поддетектор/), act: "click" },
      { say: "Типов десять, поэтому у списка есть поиск. Введём «вход».", at: q("#dwRight .dw-new-q"), act: "type", text: "вход" },
      { say: "Остался один тип: «Вход в область». Выберем его.", at: when(() => /Показано 1 из/.test(document.querySelector("[data-dw-new-x]")?.textContent || ""), q("#dwRight .dw-new-c:not([hidden])")), act: "click" },
      { say: "Консоль добавила поддетектор в черновик, и его область появилась на кадре. На сервере он появится после «Применить».", at: when(() => document.querySelector("[data-dw-sub].sel"), q("#main .dw-stage")) },
      { say: "Размер объекта у поддетектора можно только читать. Поддетектор получает объекты от детектора, поэтому у них общий размер. Размер меняют в детекторе: кнопка открывает нужный раздел.", at: when(() => document.querySelector("[data-dw-sub].sel"), byText("#dwRight .dw-sub-b button", /Изменить размер у детектора/)), act: "click" },
      { say: "Консоль ещё не создала поддетектор на сервере. Откроем план.", at: () => dwFoot()?.querySelector(".btn.pri"), act: "click" },
      { say: "Применим план. Консоль создаст поддетектор одной операцией.", at: byText("#bmodal.open .btn.pri", /^Применить/), act: "click" },
      { say: "Вернёмся на вкладку «Поддетекторы».", at: when(() => !dwFoot(), q('#main [data-dw-ptab="sub"]')), act: "click" },
      { say: "Поддетектор «Вход в область» теперь в списке. Он получил номер на сервере, и консоль читает его оттуда.", at: when(() => !dwFoot() && document.querySelectorAll("#dwRight [data-dw-sub]").length === 3, byText("#dwRight [data-dw-sub]", /Вход в область/)) },
      { say: "Итог: детектор находит объекты, а каждый поддетектор отдельно решает, когда сработать. Теперь поддетектор есть на сервере." },

      { ch: { id: "settings", title: "Настройки детектора", why: "Настройки меняют то, что детектор замечает. Консоль ничего не отправляет на сервер, пока вы не проверите план и не нажмёте «Применить»." },
        say: "«Трекинг» показывает на кадре рамки объектов, которые нашёл детектор. Скроем их.",
        before: dwOpen(TRK, "det"), at: byText("#main .dw-lay button", /^Трекинг$/), act: "click" },
      { say: "«Треки» показывают траектории объектов за последние секунды. Скроем и их.", at: when(() => !dw.lay.obj, byText("#main .dw-lay button", /^Треки$/)), act: "click" },
      { say: "Раздел «Размер объекта»: детектор не замечает объекты меньше и больше этих размеров. Консоль считает размер в процентах кадра.", at: q("#dwRight [data-dw-size-sec]") },
      { say: "Увеличим минимальный размер: введём 5.", before: dwSize("min.0"), at: when(() => !dw.lay.trk, q('#dwRight [data-dw-size="min.0"]')), act: "type", text: "5" },
      { say: "Полоса внизу появляется, только когда есть изменения: «Не применено: 1». «Сбросить» возвращает прежние настройки, «Показать план» открывает список изменений.", at: dwFoot },
      { say: "Откроем план.", at: () => dwFoot()?.querySelector(".btn.pri"), act: "click" },
      { say: "План показывает каждую строку: параметр, что было и что станет. Здесь одна строка: «Размер объекта не меньше».", at: q("#bmodal.open .bk-table") },
      { say: "Вернёмся к окну. Консоль ещё не отправила настройки на сервер.", at: btn(/^Назад$/), act: "click" },
      { say: "Итог: правка лежит в черновике. На сервер она уйдёт только после «Применить»." },

      { ch: { id: "compare", title: "Сработки до и после", why: "Вкладка сравнивает, сколько сработок давали прежние настройки и сколько дают новые. Так видно, помогла ли правка." },
        say: "Под кадром вкладка «Сработки до и после новых настроек». Период выбирают кнопками от 5 до 60 мин. Выберем 30 мин.",
        before: dwOpen(TRK, "det"), at: byText("#main [data-dw-prev] .dw-seg button", /^30 мин$/), act: "click" },
      { say: "Плитка «Текущие настройки» показывает число сработок за период. У плитки «Новые настройки» пока прочерк. На шкале верхний ряд показывает сработки текущих настроек, нижний ряд показывает сработки новых.", at: q("#main [data-dw-cmp]") },
      { say: "Сработки здесь — это модель. Браузер создаёт их, сервер их не отдаёт. В обучении модель работает на учебных данных.", at: q("#main .dw-stub") },
      { say: "Чтобы сравнить, увеличим минимальный размер объекта: введём 10.", before: dwSize("min.0"), at: q('#dwRight [data-dw-size="min.0"]'), act: "type", text: "10" },
      { say: "Откроем план.", at: () => dwFoot()?.querySelector(".btn.pri"), act: "click" },
      { say: "Применим настройки. Консоль отправит их на сервер одной операцией.", at: byText("#bmodal.open .btn.pri", /^Применить/), act: "click" },
      // Уведомление живёт 10 с: на шаге его держит курсор (mouseenter ставит отсчёт на паузу)
      { say: "Полоса изменений исчезла: консоль применила настройки. В уведомлении есть кнопка «Отменить». Она вернёт прежние настройки целиком.", at: () => { const e = !dwFoot() && document.getElementById("ttu-undo"); if (e && !e._tourHold) { e._tourHold = 1; e.dispatchEvent(new MouseEvent("mouseenter")); } return e || null; } },
      { say: "Новые настройки только начали работать, и сработок у них пока нет. Время превью идёт как в жизни. Ускорим его: ×60.", at: byText("#main .dw-stub .dw-vs button", /^×60$/), act: "click" },
      { say: "Плитка с прогнозом сравнивает новые настройки с текущими. Она пишет, меньше или больше сработок, и показывает разницу числом.", // Часы превью идут по кадрам браузера. Когда кадров нет (окно скрыто), дойти до прогноза помогает ручной ход часов
        before: async () => { const wait = (ms) => new Promise((r) => setTimeout(r, ms)), T0 = dw.T; await wait(700); for (let t = 0; dw.T === T0 && t < 40 && !document.querySelector("#main .dw-k.fc:not(.off)"); t++) { dw.T += 3 * dw.tsp; dwRefresh(); await wait(25); } },
        at: when(() => document.querySelector("#main .dw-k.fc:not(.off)"), q("#main .dw-k.fc")) },
      { say: "Итог: вы видите, как новые настройки меняют число сработок, и при необходимости возвращаете прежние одной кнопкой." },
    ];
  })(),
});

Tour.add({
  id: "storage",
  title: "Как устроены хранилища",
  why: "Хранилище держит записи камер. Камера без хранилища не пишет архив, поэтому важно видеть, что куда пишется.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const dom = () => domains[0];
    const domRow = () => document.querySelector(`#tree .n[data-pick="${dom().id}"]`);
    const groupRow = (re) => byText("#tree .n", re);
    const emptySrv = () => dom().servers.find((s) => !serverArchives(s.id).length && serverDisks(s.id).length);
    return [
      { ch: { id: "table", title: "Таблица хранилищ", why: "Таблица сразу показывает все хранилища домена и их владельцев. Дерево открывать не нужно." },
        say: "Раздел открывается таблицей хранилищ домена.", before: () => { goApp("hw"); setSlice("arch"); pick(dom().id, { force: true }); }, at: q(".as-tbl") },
      { say: "У каждого хранилища виден владелец: сервер или домен.", at: q(".as-tbl tbody tr td:nth-child(2)") },
      { say: "Значки разные. Бирюзовый диск — хранилище на дисках сервера, фиолетовая сеть — сетевое. Вид читается по цвету и по форме.", at: () => document.querySelector(".as-tbl .ici-asnet")?.closest("td") },
      { say: "Сетевые хранилища — первая группа в дереве. Клик по ней отбирает их в таблице.", at: groupRow(/Сетевые хранилища/), act: "click" },
      { say: "В таблице остались только сетевые. Отбор меняют кнопками над таблицей.", at: byText(".as-chip.on", /Сетевые/) },
      { say: "Клик по строке домена возвращает все хранилища и не сворачивает дерево.", at: domRow, act: "click" },
      { say: "Список на месте, в таблице снова все хранилища. Сворачивает только стрелка.", at: () => (archTbl.kind === "all" && open.has(dom().id) ? domRow()?.querySelector(".tw") : null) },

      { ch: { id: "unrecorded", title: "Что осталось без записи", why: "Камера без хранилища не пишет архив. Такие камеры и серверы собраны в дереве отдельно." },
        say: "От хранилища к его серверу — один клик по имени владельца.", at: q(".as-tbl .as-link"), act: "click" },
      { say: "Открылись хранилища этого сервера и сетевые хранилища домена. Строка сервера в дереве моргнула: видно, куда пришли.", at: () => (find(sel)?.n.type === "server" ? document.querySelector("#tree .n.on") : null) },
      { say: "Серверы без хранилищ собраны в одну группу.", at: groupRow(/Серверы без хранилищ/) },
      { say: "В самом низу дерева — камеры без привязки к архиву. Откроем этот пункт.", at: q("#tree .as-norec-top"), act: "click" },
      { say: "Здесь все камеры, которым не назначено хранилище. Камеры сгруппированы по доменам.", at: q("#tree .as-norec-top ~ .n[data-pick]"), act: "click" },
      { say: "Камера открылась сразу на вкладке «Архив»: здесь её привязывают к хранилищу.", at: () => (find(sel)?.n.type === "camera" ? document.querySelector(".tabs .tab.on") : null) },

      { ch: { id: "new", title: "Новое хранилище", why: "Создать хранилище можно с любого объекта раздела. Мастер сам подставит то, что уже известно." },
        say: "Кнопка одна, на любом объекте раздела.", before: () => pick(dom().id, { force: true }), at: byText(".hd .btn", /Создать хранилище/), act: "click" },
      { say: "С домена подставлены весь домен и сетевой вид, но можно выбрать любой вид.", at: q("#bmBody .an-srv select") },
      { say: "Выбираем локальное хранилище.", at: byText("#bmBody .an-kind", /Локальное/), act: "click" },
      { say: "Локальному нужен сервер. «Весь домен» из списка исчез, а «Далее» не работает, пока сервер не выбран.", at: () => (an?.kind === "local" ? document.querySelector("#bmBody .an-srv select") : null) },
      { say: "Выбрали сервер: идём дальше, к его настройкам.", before: () => anSet("server", emptySrv().id), at: () => (an?.server ? document.querySelector("#bmFoot .btn.pri") : null), act: "click" },
      { say: "Имя и глубина хранения.", at: () => (an?.step === 1 ? document.querySelector("#bmFoot .btn.pri") : null), act: "click" },
      { say: "Первый том: диски этого сервера.", at: () => (an?.step === 2 ? document.querySelector("#bmFoot .btn.pri") : null), act: "click" },
      { say: "Проверяем и создаём.", at: () => (an?.step === 3 ? document.getElementById("anCreate") : null), act: "click" },
      { say: "Раздел остался тем же: новое хранилище выбрано и открыто, его строка в дереве моргает.", at: () => (find(sel)?.n.type === "archive" ? document.querySelector("#tree .n.on") : null) },
      { say: "На сервере та же кнопка, но контекст другой.", before: () => pick(dom().servers.find((s) => serverArchives(s.id).length).id, { force: true }), at: byText(".hd .btn", /Создать хранилище/), act: "click" },
      { say: "Сразу подставлены этот сервер и локальный вид. Сервер можно сменить, переходить никуда не нужно.", at: q("#bmBody .an-srv select") },
      { say: "Итог: владелец виден в каждой строке, создать можно откуда угодно, а после создания вы остаётесь на месте.", before: () => archNewCancel() },
    ];
  })(),
});

Tour.add({
  id: "wizards",
  title: "Как работают мастера создания",
  why: "Все мастера устроены одинаково. Освоив один, вы умеете пользоваться всеми.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const row = (re) => byText(".srv-list .it", re);
    const dom = () => domains[0];
    return [
      { ch: { id: "steps", title: "Шаги и подвал", why: "Шаги показывают, сколько осталось, а подвал всегда говорит, чего не хватает." },
        say: "Серверы, хранилища, роли, детекторы создаются одинаково. Начнём с серверов.",
        before: () => { closeWizard(); wzDrop("srv"); goApp("hw"); pick(dom().id); goTab("gen"); }, at: byText(".dom-acts .btn", /Серверы/), act: "click" },
      { say: "Окно по центру. Сверху шаги: это кнопки, на пройденный шаг можно вернуться.", at: q("#wst .dc-steps") },
      { say: "Отмечаем сервер. Адреса вводим здесь же.", at: row(/10\.30\.0\.15/), act: "click" },
      { say: "Подвал один и тот же везде: «Отмена», итог выбора, «Назад» и главная кнопка. Без выбора «Далее» неактивна, а причина написана рядом.", at: q("#wizDr .df") },
      { say: "Идём дальше.", at: q("#wn"), act: "click" },
      { say: "Окно само сжалось под шаг. Последний шаг и есть план: ничего ещё не добавлено, а кнопка называет результат.", at: q("#wn") },

      { ch: { id: "draft", title: "Черновик", why: "Незаконченная работа не теряется, даже если вас отвлекли или окно закрылось случайно." },
        say: "Клик мимо окна и Escape его не закрывают. Закрыть можно здесь: выбор не пропадёт.", at: q('#wizTools .dc-x[aria-label="Закрыть"]'), act: "click" },
      { say: "Незавершённое видно в любом разделе. Его можно продолжить или удалить. Пароли в браузере не хранятся.", at: q("#wzDock-srv .btn.pri"), act: "click" },
      { say: "Вернулись на то же место. «Отмена» — единственная кнопка, которая удаляет черновик, и она спросит.", at: q("#wc"), act: "click" },
      { say: "Подтверждаем.", at: q("#confirmOk"), act: "click" },
      { say: "Черновик удалён только после вашего подтверждения." },

      { ch: { id: "storage", title: "Мастер хранилища", why: "Длинная настройка разбита на четыре шага, поэтому на экране только то, что нужно сейчас." },
        say: "Хранилище создаётся за четыре шага.", before: () => { const s = dom().servers.find((x) => !isUnallocated(x.id)); pick(s.id, { force: true }); addArchive(s.id); }, at: q("#bmBody .dc-steps") },
      { say: "На шаге выбора вида окно широкое: нужны карточки. Дальше оно станет уже.", at: byText("#bmFoot .btn.pri", /Далее/), act: "click" },
      { say: "Настройки хранилища.", at: byText("#bmFoot .btn.pri", /Далее/), act: "click" },
      { say: "Первый том.", at: byText("#bmFoot .btn", /Далее/), act: "click" },
      { say: "Проверка и кнопка с результатом.", at: q("#anCreate") },

      { ch: { id: "role", title: "Мастер роли", why: "Роль задаёт, что человек может делать и какие камеры видит. Мастер проводит по этим решениям по порядку." },
        say: "Раздел «Права»: новая роль. Шаги те же, окно по центру.", before: () => { wzCancelQuiet("arch"); goApp("acc"); accWzOpen(); }, at: q("#accWizSt .dc-steps") },
      { say: "Пока имя пусто, итог в подвале говорит, чего не хватает.", at: q("#accWizFt .dc-sum") },
      { say: "Вводим имя: итог в подвале сразу меняется, и «Далее» становится активной.", at: q('#accWizBd input[type="text"]'), act: "type", text: "Дежурные" },
      { say: "Идём к правам.", at: q("#accWizFt .btn.pri"), act: "click" },
      { say: "На шаге «Права» окно шире и делится на две колонки: функции слева, камеры по папкам справа. У каждой колонки своя прокрутка.", at: q("#accWizBd .wz-col:last-child") },
      { say: "Следующий шаг.", at: q("#accWizFt .btn.pri"), act: "click" },
      { say: "Шаг «Кому». Выберем группы и пользователей.", at: byText("#accWizBd .acc-seg button", /Группы и пользователи/), act: "click" },
      { say: "Здесь такие же две колонки. Для других вариантов окно остаётся узким: его размер идёт за содержимым.", at: q("#accWizBd .wz-col:last-child") },

      { ch: { id: "short", title: "Короткие мастера", why: "Даже короткий мастер хранит черновик, поэтому начатое можно закончить позже." },
        say: "Новая группа пользователей: вводим название.", before: () => { wzCancelQuiet("accWiz"); accUgOpen(); }, at: q("#accUgBd input"), act: "type", text: "Ночная смена" },
      { say: "Закрываем окно: название не пропадёт.", at: q('#accUg .dc-x[aria-label="Закрыть"]'), act: "click" },
      { say: "Группа ждёт в доке, как и другие черновики. Продолжим.", at: q("#wzDock-accUg .btn.pri"), act: "click" },
      { say: "Название на месте. «Отмена» снова спросит, прежде чем удалить черновик.", at: byText("#accUgFt .btn", /Отмена/), act: "click" },
      { say: "Подтверждаем.", at: q("#confirmOk"), act: "click" },
      { say: "Так же устроены устройства, служба, единица СКУД, правило, пользователь, группа пользователей, каталог, группа каталога и импорт из CSV." },
    ];
  })(),
});

Tour.add({
  id: "rules",
  title: "Как создать правило автоматизации",
  why: "Правило само реагирует на событие: записывает видео, поднимает тревогу или шлёт письмо. Начните с простого правила «если — то». Затем добавьте условие и ветки: при ответе «да» правило делает одно, при ответе «нет» — другое.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const eventSel = q('select[aria-label^="Вид события 1"]');
    const option = (re) => byText(".cbx-o", re);
    const newRuleBtn = byText("#aside .btn", /^\s*Правило\s*$/);
    const openNew = () => { wzDrop("rule"); closeBulkModal(); goApp("rules"); };
    const stepSel = (ps) => q(`select[data-ks="${ps}"]`);
    const addBtn = (lp) => q(`[data-fk="add:${lp}"]`);
    const stepRow = (ps) => () => stepSel(ps)()?.closest(".rl-row");
    const whenPick = () => eventSel()?.closest(".rl-row")?.querySelector(".rl-pick");
    const condSel = q('select[aria-label^="Вид условия 1"]');
    const schedSel = q('select[aria-label^="Расписание условия 1"]');
    const branch = (re) => byText(".rl-br", re);
    const saved = () => (document.getElementById("bmodal")?.classList.contains("open") || ruleSaving || ruleDiffLive().length ? null : q(".rl-seg")());
    // Главы о цепочке правила: правило создаётся по шаблону, список выбирается тремя шагами (открыть, ввести, выбрать)
    const fresh = (tpl, start) => () => { wzDrop("rule"); closeBulkModal(); goApp("rules"); if (ruleDraft) ruleRestore(); rnw = { step: 1, start: start || "event", tpl, preset: null }; ruleNewCreate(); };
    const evSel = (i) => q(`select[aria-label^="Вид события ${i}"]`);
    const btn = (name) => byText(".btn, .stchip", new RegExp(`^\\s*${name}\\s*$`));
    const rowOf = (sel) => () => sel()?.closest(".rl-row");
    const choose = (at, text, label, open, type) => [
      { say: open, at, act: "click" },
      { say: type, at: q(".cbx-q"), act: "type", text },
      { say: `Остался короткий список. Выбираем «${label}».`, at: option(new RegExp(label.replace(/[()]/g, "\\$&"))), act: "click" }];
    const evStep = (kind, say) => ({ say, before: () => setTriggerKind(0, String(TRIGGER_KINDS.findIndex((k) => k.kind === kind))), at: rowOf(evSel(1)) });
    const actKind = (label) => "a:" + ACTION_KINDS.findIndex((k) => k.label === label);
    const actStep = (label, say, then) => ({ say, before: () => { setStepKind("0", actKind(label)); if (then) then(); }, at: stepRow("0") });
    // Главы о режимах: ручное включение в конце главы снимается, расписания и режимы не меняются
    const when = (cond, at) => () => (cond() ? at() : null);
    const modesOpen = () => { closeBulkModal(); goApp("rules"); ruleOpen("modes"); };
    // Перемотка к главе проходит прежние главы и оставляет черновик правила: без сброса переход к режимам спросит «Изменения не применены»
    const modesClean = () => {
      if (typeof ruleDraft !== "undefined" && ruleDraft && ruleDiffLive().length) ruleRestore();
      if (umManNow()) API.post("/modes/current", { modeId: null, until: null }).then((c) => { modeCurApply(c); hdModePaint(); ruleIdxDrop(); paint(); });
    };
    const svcMode = () => UMODES.find((m) => m.sys), workMode = () => UMODES.find((m) => m.code === "work"), noMode = () => ({ id: "none" });
    const modeRow = (pick) => () => {
      const m = pick();
      return m && document.querySelector(`tr[data-mode="${m.id}"]`);
    };
    const onModes = (at) => when(() => document.querySelector("tr.um-base"), at);
    const ruleOfMode = () => rules.find((r) => r.name === "Охрана входа ночью")?.id;
    const dlg = (at) => when(() => document.querySelector("#bmodal.open"), at);
    return [
      { ch: { id: "start", title: "Способ запуска", why: "Способ запуска определяет, какие шаблоны и настройки подойдут правилу." },
        say: "Новое правило создаётся здесь.", before: openNew, at: newRuleBtn, act: "click" },
      { say: "Правило запускается событием, по расписанию или вручную из меню оператора. Оставляем запуск по событию.", at: q("#bmodal [data-rnw]") },
      { say: "Идём к шаблонам.", at: byText("#bmodal .btn", /Далее/), act: "click" },

      { ch: { id: "simple", title: "Простое правило: «Если» и «То»", why: "Простое правило отвечает на два вопроса: что случилось и что сделать." },
        say: "Соберём правило сами. Выбираем «С нуля»: событие и действие вы зададите сами.", at: byText("#bmodal .rl-opt", /С нуля/), act: "click" },
      { say: "Создаём правило. Оно создаётся выключенным и не сработает, пока вы его не включите.", at: byText("#bmodal .btn", /Создать правило/), act: "click" },
      { say: "Блок «Если» говорит, что случилось. Добавляем событие.", at: byText(".btn", /^\s*Добавить событие\s*$/), act: "click" },
      { say: "Система предложила движение. Вид события можно сменить в этом списке.", at: eventSel },
      { say: "Осталось сказать, на какой камере ждать движение.", at: whenPick, act: "click" },
      { say: "Находим камеру по названию.", at: q("#rpQ"), act: "type", text: "Главный вход" },
      { say: "Отмечаем камеру.", at: byText("#rpList .rl-pk[data-tok]", /Главный вход/), act: "click" },
      { say: "Подтверждаем выбор.", at: q("#rpOk"), act: "click" },
      { say: "Блок «То» говорит, что сделать. Добавляем действие.", at: addBtn(""), act: "click" },
      { say: "Новое действие — запись. Камеру система взяла из события, а запись идёт, пока идёт движение.", at: stepRow("0") },
      { say: "Простое правило собрано: если на главном входе движение, то камера записывает видео. Чтобы сохранить его, нажмите внизу «Показать план», затем «Применить».", at: stepRow("0") },

      { ch: { id: "condition", title: "Сложное правило: «При условии»", why: "Условие решает, нужно ли выполнять действия в этот раз. Действия не выполняются там, где они только мешают." },
        say: "Движение днём — норма, а ночью — повод насторожиться. Блок «При условии» стоит между «Если» и «То». Добавляем условие.", at: byText(".btn", /^\s*Добавить условие\s*$/), act: "click" },
      { say: "Вид условия задаёт, что проверить: время, режим объекта, охрану, запись или связь с устройством. Оставляем время.", at: condSel },
      { say: "Расписание берётся из библиотеки. Открываем список.", at: schedSel, act: "click" },
      { say: "Находим ночное расписание.", at: q(".cbx-q"), act: "type", text: "ночь" },
      { say: "Выбираем «Ночь».", at: option(/^\s*Ночь\s*$/), act: "click" },
      { say: "Условие проверяется в момент запуска. Если оно не выполнено, правило ничего не делает, а в журнале остаётся запись о пропуске.", at: () => condSel()?.closest(".rl-row") },

      { ch: { id: "branches", title: "Ветки: «да» и «нет»", why: "Шаг с ветками выбирает действие по ответу: при «да» правило делает одно, при «нет» — другое." },
        say: "Самый понятный шаг с ветками — вопрос оператору. Добавляем в «То» новый пункт.", at: addBtn(""), act: "click" },
      { say: "В этом списке есть и действия, и шаги хода выполнения. Открываем его.", at: stepSel("1"), act: "click" },
      { say: "Находим шаг по названию.", at: q(".cbx-q"), act: "type", text: "спросить" },
      { say: "Выбираем «Спросить оператора».", at: option(/Спросить оператора/), act: "click" },
      { say: "Здесь вопрос, роль и время на ответ. Если оператор не ответил, правило считает ответ тем, что вы выбрали в поле «если нет ответа — считать».", at: stepRow("1") },
      { say: "Под шагом появились две ветки. «Если подтвердил» — это ответ «да». Добавляем сюда действие.", at: addBtn("1.yes"), act: "click" },
      { say: "Открываем список.", at: stepSel("1.yes.0"), act: "click" },
      { say: "Ищем тревогу.", at: q(".cbx-q"), act: "type", text: "тревогу" },
      { say: "При «да» правило поднимет тревогу.", at: option(/Поднять тревогу/), act: "click" },
      { say: "Камеру система взяла из события: тревога поднимется там, где было движение.", at: stepRow("1.yes.0") },
      { say: "«Если отклонил» — это ответ «нет». Здесь действие другое.", at: addBtn("1.no"), act: "click" },
      { say: "Открываем список.", at: stepSel("1.no.0"), act: "click" },
      { say: "Ищем письмо.", at: q(".cbx-q"), act: "type", text: "письмо" },
      { say: "При «нет» правило отправит письмо старшему смены.", at: option(/Отправить письмо/), act: "click" },
      { say: "Правило показывает ошибку: не заполнено поле «Кому». Правило с ошибкой нельзя применить включённым.", at: q(".nt.err") },
      { say: "Заполняем адрес и тему. В теме можно использовать переменные, например название камеры.",
        before: () => { const ps = "1.no.0"; setActionField(ps, "to", "senior@example.com"); setActionField(ps, "subj", "Ложное движение: {камера}"); }, at: stepRow("1.no.0") },
      { say: "Теперь у правила два пути. Оператор ответил «да» — тревога. Оператор ответил «нет» — письмо.", at: () => branch(/если подтвердил/)()?.parentElement },
      { say: "Проверим правило без риска. Пробный запуск показывает, что сделало бы правило, но ничего не выполняет.", at: q('[data-fk="check"]'), act: "click" },
      { say: "Здесь можно выбрать ответ оператора: подтвердил, отклонил или нет ответа. Правило пройдёт по этой ветке.", at: () => byText("#bmodal label", /Спросить оператора/)()?.parentElement },
      { say: "Закрываем проверку.", at: byText("#bmodal .btn", /^\s*(Закрыть|Отменить)\s*$/), act: "click" },
      { say: "Изменения вступают в силу только после плана. Открываем его.", at: byText("#ruleFoot .btn", /Показать план/), act: "click" },
      { say: "План перечисляет, что изменится. Применяем.", at: q("#rpApply"), act: "click" },
      { say: "Правило сохранено, но ещё выключено. Сначала включите «Только журнал» и посмотрите запуски, затем выберите «Работает».", at: saved },

      { ch: { id: "template", title: "Шаблон", why: "Шаблон сразу даёт рабочую логику: остаётся выбрать устройства и получателей." },
        say: "Похожее правило можно собрать быстрее. Снова создаём новое правило.", before: openNew, at: newRuleBtn, act: "click" },
      { say: "Идём к шаблонам.", at: byText("#bmodal .btn", /Далее/), act: "click" },
      { say: "Шаблоны разбиты на группы. Пустое правило «С нуля» доступно всегда.", at: q("#bmodal .rl-tpl-g") },
      { say: "Система предлагает только те шаблоны, которые она умеет выполнить. Берём пересечение линии.", at: q('#bmodal [data-tpl="line"]'), act: "click" },
      { say: "Создаём правило. Оно создаётся выключенным и не сработает, пока вы его не включите.", at: byText("#bmodal .btn", /Создать правило/), act: "click" },
      { say: "Шаблон заполнил блоки «Если» и «То». Устройства он оставил пустыми: их выбираете вы.", at: eventSel },

      { ch: { id: "search", title: "Поиск в длинном списке", why: "В списке событий много пунктов. Поиск находит нужный быстрее, чем прокрутка." },
        say: "Открываем список событий. Длинный список всегда открывается с полем поиска.", at: eventSel, act: "click" },
      { say: "Пункты разбиты на группы, а текущий пункт виден сразу. Вводим часть названия.", at: q(".cbx-q"), act: "type", text: "обрыв" },
      { say: "Список сузился, совпадения подсвечены, внизу итог. Стрелки и Enter выбирают пункт, Esc отменяет. Выбираем мышью.", at: option(/Обрыв потока/), act: "click" },
      { say: "Короткий список, до семи пунктов, остаётся обычным: его быстрее выбрать глазами. Теперь выберите камеру и включите правило." },

      { ch: { id: "logic", title: "«Или» между событиями и условиями", why: "Несколько событий могут запускать правило по одному или только все вместе. То же выбирают для условий." },
        say: "Начинаем с шаблона «Движение — запись». Добавляем второе событие в блок «Если».", before: fresh("mrec"), at: btn("Добавить событие"), act: "click" },
      { say: "Второе событие связано с первым словом «или»: правило запускает любое из событий.", at: q(".rl-logic") },
      ...choose(evSel(2), "дым", "Детектор: дым", "Выбираем второе событие. Открываем список.", "Вводим часть названия."),
      { say: "Вторая строка подписана «или». Подпись под строками объясняет, что это значит.", at: () => evSel(2)()?.closest(".rl-row")?.querySelector(".rl-n") },
      { say: "Выбираем «все события».", at: btn("Правило запускается, если пришли все события"), act: "click" },
      { say: "Строка подписана «и», а рядом появилось окно: оба события должны произойти в пределах этого числа секунд.", at: q(".rl-win") },
      { say: "Возвращаем «любое событие».", at: btn("Правило запускается, если пришло любое событие"), act: "click" },
      { say: "Условия блока «При условии» тоже можно связать по-разному. Добавляем первое условие.", at: btn("Добавить условие"), act: "click" },
      { say: "Добавляем второе условие.", at: btn("Добавить условие"), act: "click" },
      { say: "По умолчанию условия идут через «и»: должны выполниться все.", at: btn("Правило выполняется, если верны все условия") },
      { say: "Выбираем «любое условие».", at: btn("Правило выполняется, если верно любое условие"), act: "click" },
      { say: "Вторая строка условий подписана «или»: достаточно одного выполненного условия.", at: () => { const rows = [...document.querySelectorAll('select[aria-label^="Вид условия"]')]; return rows.at(-1)?.closest(".rl-row")?.querySelector(".rl-n"); } },
      { say: "Переключатель действует на весь блок. Выражение «A и (B или C)» с ним собрать нельзя." },

      { ch: { id: "events", title: "Новые события", why: "События собраны по группам: связь, детекторы, тревоги, запись, охрана, сервер. Каждое выбирают в первой строке блока «Если»." },
        say: "Новые события выбираются в первой строке блока «Если».", before: fresh("mrec"), at: evSel(1) },
      evStep("device.lost", "Связь с камерой пропала. Поле порога отсекает короткие обрывы. Рядом есть события «связь восстановлена», «ошибка авторизации» и «включена в настройках»."),
      evStep("tamper", "Камеру закрыли или сдвинули. Рядом есть детекторы огня и дыма."),
      evStep("face.list", "Лицо есть в списке или нет в списке. Уточнение выбирают в той же строке."),
      evStep("plate.list", "То же для номера. На этом событии построен шаблон шлагбаума."),
      evStep("alarm.closed", "У тревоги несколько событий: начата, взята в работу, обработана, подтверждена, подозрительная, ложная, пропущена. На каждое можно построить свою реакцию."),
      evStep("rec.lost", "Запись: началась, остановилась, нет записи в архив, запись в архив восстановлена."),
      evStep("arm.off", "Охрана: камера поставлена, поставлена в приватном режиме, снята."),
      evStep("ptz.failed", "Поворотная камера: пришла в пресет, сдвинули вручную, не пришла в пресет."),
      evStep("output.on", "Выход устройства включился. У события есть окончание, поэтому действие может идти, пока выход включён."),
      evStep("server.down", "Сервер: нет связи, связь восстановлена. Рядом есть событие «нет связи с сервером лицензий»."),
      evStep("load.high", "Нагрузка сервера выше порога. Уточнения: что считать, какой процент и как меняется нагрузка."),
      evStep("sched.edge", "Начало или конец расписания тоже событие."),
      evStep("volume.error", "Ошибка тома архива. Событие относится к тому: в окне выбора том стоит под своим хранилищем."),
      { say: "Эти события отправляет сервер. Правило выбирает их так же, как движение." },

      { ch: { id: "flow", title: "Проверка и ход выполнения", why: "Шаг «Проверить и разветвить» выбирает ветку по состоянию системы. Другие шаги ждут конца предыдущего шага или прерывают выполнение." },
        say: "Шаблон «Нет записи: письмо» запускается по расписанию и повторяется с интервалом. Галочка «Повторять с интервалом» включает повтор.", before: fresh("norec", "sched"), at: () => [...document.querySelectorAll("#main label")].find((e) => /Повторять/.test(e.textContent) && e.textContent.length < 80) },
      { say: "Шаг «Проверить и разветвить» читает состояние системы на момент шага и идёт по одной из двух веток.", at: stepSel("0") },
      { say: "Здесь проверка записи в архиве за последний час.", at: stepRow("0") },
      { say: "Ветка «если да»: запись есть. Шаг «Прервать выполнение» заканчивает правило.", at: branch(/если да/) },
      { say: "Ветка «если нет»: записи нет, уходит письмо.", at: branch(/если нет/) },
      { say: "Проверять можно и другое. У проверки «Камера на охране» нет периода, поэтому поле периода ушло.", before: () => setCtlField("0", "what", "armed"), at: stepRow("0") },
      { say: "Также можно проверить защищённую запись и связь с устройством.", before: () => setCtlField("0", "what", "online"), at: stepRow("0") },
      { say: "Возвращаем проверку записи и добавляем шаг в ветку «если нет».", before: () => setCtlField("0", "what", "record"), at: addBtn("0.no"), act: "click" },
      ...choose(stepSel("0.no.1"), "дождаться", "Дождаться конца предыдущего шага", "Новый пункт просит выбрать вид. Открываем список.", "В группе «Ход выполнения» теперь три новых шага."),
      { say: "Шаг ждёт конца письма, но не дольше заданного времени. Только после этого начинается следующий шаг.", at: stepRow("0.no.1") },
      { say: "Ветки могут быть вложенными. Добавляем ещё один шаг.", at: addBtn("0.no"), act: "click" },
      ...choose(stepSel("0.no.2"), "ждать соб", "Ждать событие", "Выбираем шаг с собственными ветками.", "Вводим часть названия."),
      { say: "Это второй уровень ветвления. Глубже двух уровней шаги с ветками не предлагаются.", at: stepRow("0.no.2") },
      { say: "Номер шага показывает путь: «1Б.3А.1» значит шаг 1, ветка Б, шаг 3, ветка А, шаг 1." },

      { ch: { id: "actions", title: "Новые действия", why: "Новые действия дополняют запись, тревогу, письмо и веб-запрос. Сервер объявляет их в описаниях видов и в справочнике." },
        say: "Список действий с поиском общий для действий и шагов хода выполнения. Показываем новые действия по очереди.", before: fresh("mrec"), at: stepSel("0") },
      actStep("Записывать", "Запись получила два поля: секунды до начала и число кадров в секунду."),
      actStep("Экспортировать кадр или видео", "Экспорт кадра или видео вокруг события."),
      actStep("Начать репликацию", "Репликация: вокруг события или за время, пока сервер был недоступен."),
      actStep("Обход поворотной камеры", "Обход поворотной камеры: начать или остановить."),
      actStep("Отправить письмо", "Письмо может взять вложение: кадр или видео."),
      actStep("Push-уведомление", "Push-уведомление: заголовок, текст и вложение."),
      actStep("Воспроизвести звук у оператора", "Звук в клиенте оператора для выбранной роли."),
      actStep("Голосовое сообщение от оператора", "Голосовое сообщение от оператора: выбирают роль."),
      actStep("Команда экрану оператора", "Команда экрану: выбрать камеру, показать карту, открыть архив, пометить камеру, начать слайд-шоу, вернуть раскладку."),
      actStep("Запустить программу у оператора", "Программа на компьютере оператора."),
      actStep("Запустить программу на сервере", "Программа на сервере с аргументами."),
      actStep("Включить или выключить службу", "Служба на сервере: включить или выключить."),
      actStep("Воспроизвести звук на устройстве", "Звук на динамике устройства."),
      actStep("Управлять реле", "Реле можно включить и выключить, а не только щёлкнуть. Поле импульса показано только для импульса.", () => setActionField("0", "state", "on")),
      actStep("Встать в пресет", "Пресет получил скорость и время удержания."),
      actStep("Поднять тревогу", "Тревога: когда поднимать и обязателен ли комментарий оператора."),
      actStep("Закрыть тревогу", "Закрытие тревоги получило оценку: ложная, подозрительная, подтверждена."),
      actStep("Веб-запрос", "Веб-запрос: методы PUT и DELETE, авторизация, заголовки и тело. Через него собирается и сообщение в Telegram."),
      { say: "Эти действия есть, только если сервер их объявил. Консоль показывает в списке только объявленное." },

      // Режимы: режим выключает правила на время, действует один режим, расписания режимов не пересекаются. Каждая глава оставляет данные как были
      { ch: { id: "modes-what", title: "Что такое режим", why: "Режим выключает правила на время, например пока на объекте идут работы. Не надо выключать правила по одному." },
        say: "Режимы находятся в разделе «Автоматизация». Откроем их.", before: () => { modesClean(); closeBulkModal(); goApp("rules"); }, at: q('#tree [data-go="rule:modes"]'), act: "click" },
      { say: "Карточка «Сейчас» говорит, какой режим действует и сколько правил он выключил.", at: onModes(q(".mode-now")) },
      { say: "В каждый момент действует один режим. Первая строка — «Обычная работа». Это состояние по умолчанию: в нём все правила работают по своим условиям.", at: modeRow(noMode) },
      { say: "«Обычная работа» действует всё время, которое не занято расписанием другого режима. Настроек у неё нет.", at: () => modeRow(noMode)()?.querySelector("select") },
      { say: "Режим «Обслуживание» включает оператор вручную. Он выключает все правила, в том числе правила, которые появятся потом.", at: modeRow(svcMode) },
      { say: "Режим «Рабочее время» включается по расписанию. Он выключает только одно правило: «Охрана входа ночью». Остальные правила работают.", at: modeRow(workMode) },

      { ch: { id: "modes-manual", title: "Включить режим вручную", why: "Оператор включает режим сам, когда не хочет ждать расписания. Ручной режим всегда включается на срок, поэтому забытый режим кончится сам." },
        say: "Кнопка в шапке показывает действующий режим. Она есть на любом экране. Откроем её меню.", before: () => { modesClean(); modesOpen(); }, at: q("#hdMode"), act: "click" },
      { say: "Меню предлагает другие режимы. Выберем «Обслуживание».", at: byText("#tctx.open button", /Включить «Обслуживание»/), act: "click" },
      { say: "Окно говорит, что режим выключит, и спрашивает срок. Срок не больше 8 часов. Потом режим кончится сам.", at: dlg(q("#bmBody .msw")) },
      { say: "Выберем два часа.", at: dlg(byText("#bmBody .msw-o", /2 часа/)), act: "click" },
      { say: "Окно называет время конца и режим, который будет действовать потом.", at: when(() => modeSw && modeSw.min === 120, q("#bmBody p[role=status]")) },
      { say: "Включаем режим.", at: byText("#bmFoot .btn.pri", /Включить/), act: "click" },
      { say: "Кнопка в шапке стала жёлтой и показывает срок: «вручную до». Ручной режим заменил режим по расписанию.", at: when(() => umManNow(), q("#hdMode.manual")) },
      { say: "Правила тоже показывают причину. В карточке правила «Охрана входа ночью» написано, что его выключил режим.",
          before: () => ruleOpen(ruleOfMode()), at: byText("#main .nt", /выключил правило/) },
      { say: "За 10 минут до конца срока консоль напомнит и предложит «Продлить на 1 час». Вернёмся на страницу режимов.", before: () => ruleOpen("modes"), at: onModes(byText("#main .mode-now", /вручную до/)) },
      { say: "Чтобы не ждать конца срока, нажмите «Вернуть по расписанию».", at: byText("#main button", /Вернуть по расписанию/), act: "click" },
      { say: "Снова действует режим по расписанию. Шапка стала обычной.", at: when(() => !umManNow(), q("#hdMode:not(.manual)")) },

      { ch: { id: "modes-overlap", title: "Расписания режимов не пересекаются", why: "Два режима в одно время не говорят, какие правила работают. Поэтому сервер не принимает расписание, которое пересекается с расписанием другого режима." },
        say: "Режим можно включать по расписанию. Откроем список расписаний для режима «Обслуживание».", before: () => { modesClean(); modesOpen(); }, at: onModes(() => modeRow(svcMode)()?.querySelector("select")), act: "click" },
      { say: "Ищем расписание, которое уже занято режимом «Рабочее время».", at: q(".cbx-q"), act: "type", text: "Рабочие" },
      { say: "Выбираем «Рабочие дни».", at: byText(".cbx-o", /Рабочие дни/), act: "click" },
      { say: "Сервер отказал и назвал режим и время пересечения. Расписание режима не изменилось.", at: byText("#tt", /пересекается/) },
      { say: "Выберите другое расписание, и режим включится по нему. Новое расписание можно создать прямо из этого списка." },

      { ch: { id: "modes-off", title: "Какие правила выключает режим", why: "Режим выключает все правила или только выбранные. Остальные правила работают, как всегда." },
        say: "У каждого режима есть список «Выключает». Откроем выбор правил для режима «Рабочее время».", before: () => { modesClean(); modesOpen(); },
        at: onModes(() => byText(`tr[data-mode="${(workMode() || {}).id}"] .lk`, /Выбрать/)()), act: "click" },
      { say: "Правила разбиты по способу запуска. Выбранные правила отмечены флажками.", at: dlg(q("#umList")) },
      { say: "Поиск сужает длинный список. Найдём правило «Охрана входа ночью».", at: dlg(q("#umQ")), act: "type", text: "входа" },
      { say: "Нужное правило отмечено: пока режим действует, оно не сработает.", at: byText("#umList .um-ck", /Охрана входа ночью/) },
      { say: "Переключатель «Все правила» выключает и те правила, которые появятся потом.", at: byText("#bmBody .msw-o", /Все правила/) },
      { say: "Менять ничего не будем. Закрываем окно.", at: byText("#bmFoot .btn", /^\s*Отмена\s*$/), act: "click" },
      { say: "Тот же выбор есть в карточке правила: режимы, которые его выключают, отмечены флажками.", before: () => ruleOpen(ruleOfMode()), at: q("fieldset.rl-tags") },
      { say: "Итог: режим выключает правила на время, действует один режим за раз, а расписания режимов не пересекаются." },
    ];
  })(),
});


Tour.add({
  id: "assistant",
  title: "Как работать с ассистентом",
  why: "Ассистент понимает просьбу обычными словами и готовит план. Решение принимает человек: он проверяет план и сам нажимает «Применить». В показе отвечает заглушка, а не живая модель.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const field = q("#asstText"), send = q("#asstSend");
    // Кнопка, которую уже можно нажать: план в окне считается не сразу
    const ready = (at) => () => { const b = at(); return b && !b.disabled ? b : null; };
    // Панель рядом с рабочей областью: поверх она закрыла бы групповую карточку плана
    const panel = (where) => () => { goApp(where); asstVariantSet("side"); if (!asstDockOpen) asstOpen(""); };
    const fresh = (where) => () => { goApp(where); asstVariantSet("side"); asstOpen(""); };
    // Другой администратор правит правило, пока план ждёт: один раз за показ, своей версией
    const otherEdit = async () => {
      const r = rules.find((x) => x.name === "Охрана входа ночью");
      if (!r) return;
      const now = await API.get(`/rules/${r.id}`);
      if (now.purpose === "Правка другого администратора") return;
      await API.put(`/rules/${r.id}`, Object.assign(ruleBody(r), { purpose: "Правка другого администратора" }), now.version);
    };
    return [
      { ch: { id: "stub", title: "Пример с заглушкой", why: "В показе отвечает заглушка, а не живая модель. Заглушка всегда отвечает одинаково. Живая модель может ответить иначе, поэтому её ответ всегда нужно проверить." },
        say: "Кнопка «Ассистент» в шапке открывает разговор с ассистентом.", before: () => { goApp("hw"); asstVariantSet("side"); asstClose(); }, at: q("#hdAsst"), act: "click" },
      { say: "Строка над разговором напоминает: это учебный пример. Отвечает заглушка, а не живая модель.", at: q("#asstLearnNote") },

      { ch: { id: "question", title: "Просьба и вопрос", why: "Просьбу пишут обычными словами. Если данных мало, ассистент задаёт вопрос. Ответ на вопрос продолжает тот же разговор." },
        say: "В разделе правил пишем просьбу: при движении записывать видео 5 минут.", before: fresh("rules"), at: field, act: "type", text: "при движении пиши 5 минут" },
      { say: "Отправляем просьбу.", at: send, act: "click" },
      { say: "Ассистенту не хватает данных. Он спрашивает, на какой камере.", at: q("#asstAsk") },
      { say: "Отвечаем в том же поле: камера «Запасной вход».", at: field, act: "type", text: "Запасной вход" },
      { say: "Отправляем ответ.", at: send, act: "click" },
      { say: "Ассистент составил план. План ещё ничего не изменил: это только предложение.", at: q("[data-asst-rule]") },

      { ch: { id: "check", title: "Проверка плана", why: "Консоль пересказывает план словами формы. Человек сам проверяет, что изменится, и сам решает, применять ли план." },
        say: "Строка «Слова модели» — сводка модели. Модель может ошибиться, поэтому консоль подписывает её отдельно.", before: panel("rules"), at: q("#asstModelWords") },
      { say: "Ниже консоль сама пересказывает план словами формы: событие, камера, действие.", at: q("[data-asst-rule]") },
      { say: "Консоль создаст правило в режиме «Только журнал»: правило пишет в журнал, что сделало бы, и ничего не делает.", at: q("#asstBlock .asst-note") },
      { say: "Нажимаем «Применить». В показе консоль меняет только учебные данные. Настоящая система не меняется.", at: ready(q("#asstApply")), act: "click" },
      { say: "Правило создано в режиме «Только журнал». Включает его человек, когда проверит журнал.", at: q('[data-asst-row="ok"]') },

      { ch: { id: "refused", title: "Отказ", why: "Если ассистент не может выполнить просьбу, он отказывает и называет причину. Частичных планов нет." },
        say: "В новом разговоре просим то, чего в системе нет: цвет корпуса камеры.", before: fresh("hw"), at: field, act: "type", text: "поменяй цвет корпуса" },
      { say: "Отправляем просьбу.", at: send, act: "click" },
      { say: "Ассистент отказал: такого поля нет в описании устройств. Консоль ничего не изменила.", at: q("#asstRefused") },

      { ch: { id: "conflict", title: "Конфликт версии", why: "Пока план ждёт проверки, другой администратор может изменить тот же объект. Тогда консоль не записывает старый план поверх чужой правки." },
        say: "В разделе правил просим убрать шаг из правила «Охрана входа ночью».", before: fresh("rules"), at: field, act: "type", text: "в правиле Охрана входа ночью убери шаг" },
      { say: "Отправляем просьбу.", at: send, act: "click" },
      { say: "Ассистент показал, какой шаг выпадет из правила. Пока ничего не записано.", at: q("#asstApply") },
      { say: "Пока план ждал, другой администратор изменил это же правило. Нажимаем «Применить».", before: otherEdit, at: ready(q("#asstApply")), act: "click" },
      { say: "Консоль не записала план: правило изменилось после него. Чужая правка осталась на месте. Кнопка «Спросить заново» строит новый план.", at: q('[data-asst-row="fail"]') },

      { ch: { id: "ask", title: "Вопрос оператору и эскалация", why: "Ассистент составляет и правила с вопросом оператору или эскалацией. Новое правило консоль создаёт в режиме «Только журнал»: правило пишет в журнал, что сделало бы, и никого не спрашивает." },
        say: "Просим правило: при движении на камере «Главный вход» спросить оператора.", before: fresh("rules"), at: field, act: "type", text: "при движении на Главный вход спроси оператора" },
      { say: "Отправляем просьбу.", at: send, act: "click" },
      { say: "План: при движении консоль спросит оператора и подождёт ответ 60 секунд. Консоль создаст правило в режиме «Только журнал».", at: q("#asstApply") },
      { say: "Нажимаем «Применить».", at: ready(q("#asstApply")), act: "click" },
      { say: "Правило создано в режиме «Только журнал». Учебные вопросы не уходят настоящим операторам.", at: q('[data-asst-row="ok"]') },
      { say: "Эскалация устроена так же. В новом разговоре просим поднимать тревогу по уровням.", before: fresh("rules"), at: field, act: "type", text: "при движении на Главный вход эскалация" },
      { say: "Отправляем просьбу.", at: send, act: "click" },
      { say: "Уровни идут по порядку: сначала охрана, затем старший охраны. Правило снова будет в режиме «Только журнал». Включает его человек, когда проверит журнал.", at: q("#asstApply") },
    ];
  })(),
});

Tour.add({
  id: "assistant-panel",
  title: "Как устроена панель ассистента",
  why: "Разговор с ассистентом идёт в своей панели. Панель можно закрыть и работать дальше. Ассистент продолжает отвечать, а кнопка в шапке показывает состояние ответа.",
  steps: (() => {
    const q = tourQ, byText = tourText;
    const field = q("#asstText"), send = q("#asstSend:not([disabled])");
    const nth = (i) => () => document.querySelectorAll("#asstBlock .asst-u")[i];
    const hrow = (re) => byText("#asstBlock .asst-hrow", re);
    // Заглушка отвечает сразу. Показ придерживает ответ, чтобы было видно, что ход живёт без панели.
    // Показ закончился (сбой, «Попробовать самому»): курсора показа нет, поэтому ответ уходит и заглушка возвращается
    const real = API.stream, gates = [];
    let watch = 0;
    const free = () => { clearInterval(watch); API.stream = real; gates.splice(0).forEach((r) => r()); };
    const hold = () => {
      API.stream = (...args) => new Promise((r) => gates.push(r)).then(() => real.apply(API, args));
      clearInterval(watch);
      watch = setInterval(() => { if (!document.querySelector(".tour-cur")) free(); }, 500);
    };
    const start = (where) => () => {
      free();
      asstChats = []; asst = null; asstHist = false;
      asstVariantSet("auto"); asstWidthSet(400, false);
      if (asstDockOpen) asstClose();
      goApp(where); asstRender();
    };
    const fromSearch = () => document.getElementById("goAsk")?.dispatchEvent(new MouseEvent("mousedown", { bubbles: true, cancelable: true }));
    return [
      { ch: { id: "turn", title: "Разговор в своей панели", why: "Просьбу можно начать из строки поиска. Если вы закроете панель, ассистент продолжит отвечать. Кнопка в шапке покажет, когда ответ готов." },
        say: "Кнопка «Ассистент» в шапке видна всегда. Сначала начнём разговор из строки поиска.", before: start("hw"), at: q("#hdAsst") },
      { say: "Пишем в строке поиска обычный запрос.", before: hold, at: q("#gq"), act: "type", text: "сколько камер" },
      { say: "Над результатами стоит строка «Спросить ассистента». Enter оставляет запрос фильтром дерева. Ассистент получает просьбу, только когда вы выберете эту строку.", at: q("#goAsk"), act: "click" },
      { say: "Разговор открылся в панели ассистента. Консоль сняла запрос поиска, и дерево снова показывает все объекты. Ассистент ещё отвечает.", before: fromSearch, at: nth(0) },
      { say: "Панель можно закрыть в любой момент. Крестик только прячет панель, а ассистент продолжает отвечать.", at: q("#asstCloseBtn"), act: "click" },
      { say: "Панель закрылась. Кнопка в шапке показывает словами, что ассистент отвечает. Можно работать дальше.", at: q("#hdAsst.run") },
      { say: "Выбираем объект в дереве, как в обычной работе.", at: q("#tree .n[data-pick]"), act: "click" },
      { say: "Ответ пришёл. Кнопка сменила слова, а выбор в дереве остался на месте. Нажимаем кнопку.", before: free, at: q("#hdAsst.ready"), act: "click" },
      { say: "Кнопка открыла готовый ответ.", at: q("#asstAnswer") },

      { ch: { id: "chats", title: "Несколько разговоров", why: "Каждый разговор хранит все реплики. Новый разговор не останавливает тот, где ассистент ещё отвечает. История показывает состояние каждого разговора." },
        say: "Пишем первую просьбу.", before: () => { start("hw")(); asstOpen(""); }, at: field, act: "type", text: "сколько камер" },
      { say: "Отправляем её.", at: send, act: "click" },
      { say: "Продолжаем тот же разговор уточнением.", at: () => (asst && !asst.busy && asst.answer ? field() : null), act: "type", text: "а серверов сколько" },
      { say: "Отправляем уточнение.", at: send, act: "click" },
      { say: "Первая просьба и первый ответ остались в ленте, потому что лента хранит весь разговор.", at: () => (asst && !asst.busy && asst.answer ? nth(1)() : null) },
      { say: "Теперь пишем просьбу, на которую ассистент будет отвечать долго.", before: hold, at: field, act: "type", text: "сколько правил" },
      { say: "Отправляем её.", at: send, act: "click" },
      { say: "Новый разговор можно начать сразу. Ассистент продолжает отвечать в прежнем разговоре.", at: () => (asst?.busy ? document.getElementById("asstNew") : null), act: "click" },
      { say: "Кнопка с часами открывает историю разговоров.", at: q("#asstHistBtn"), act: "click" },
      { say: "Список показывает каждый разговор и его состояние. В прежнем разговоре ассистент ещё отвечает.", at: hrow(/отвечает/i) },
      { say: "Ответ пришёл, пока список был открыт. Строка показывает это. Нажимаем строку, чтобы открыть ответ.", before: free, at: hrow(/готов ответ/i), act: "click" },
      { say: "Консоль открыла ответ. Консоль хранит историю разговоров в браузере. Реплики разговора с паролем консоль не сохраняет.", at: q("#asstAnswer") },

      { ch: { id: "place", title: "Положение и ширина панели", why: "Панель стоит рядом с рабочей областью или поверх неё. «Авто» выбирает положение по ширине окна, поэтому форма не ломается на маленьком экране." },
        say: "Кнопки вверху панели выбирают её положение. «Авто» ставит панель рядом, если форме остаётся не меньше 700 px. Иначе панель стоит поверх.", before: () => { start("hw")(); asstOpen(""); }, at: q("#asstVarAuto") },
      { say: "Потянуть мышью левый край панели или нажать стрелки, чтобы изменить ширину. Консоль допускает ширину от 320 до 720 px.", before: () => asstWidthSet(520, false), at: q("#asstGrip") },
      { say: "Положение можно выбрать и вручную. Выбираем «Поверх».", before: () => asstWidthSet(400, false), at: q("#asstVarOver"), act: "click" },
      { say: "Просим изменить настройку камер. Консоль показывает план настройки в групповой карточке.", at: () => (asstVariant === "over" ? field() : null), act: "type", text: "выключи запись Главный вход" },
      { say: "Отправляем просьбу.", at: send, act: "click" },
      { say: "Панель поверх закрыла бы карточку, поэтому консоль спрятала панель. Консоль отметила объекты в дереве и показала значения в карточке. Кнопка показывает, что ассистент ждёт ответа.", at: q("#hdAsst.wait") },
      { say: "Кнопка возвращает разговор. План можно уточнить.", at: q("#hdAsst.wait"), act: "click" },
      { say: "Панель показывает план, а рядом стоит кнопка «Уточнить».", at: q("#asstSend") },
    ];
  })(),
});

Tour.add({
  id: "edge-rep",
  title: "Как настроить репликацию со встроенного хранилища",
  why: "Камера или регистратор пишет записи на свою карту или диск. Репликация переносит эти записи в архив сервера, и архив не теряет минуты без связи.",
  steps: (() => {
    const q = tourQ, byText = tourText;
  const when = (cond, at) => () => (cond() ? at() : null);
  const SRV = "20000001-0000-4000-8000-000000000000"; // «Центр/Сервер — Офис»
  const CAM = "30000013-0000-4000-8000-000000000000"; // «Главный вход»: у камеры карта памяти и ещё 13 устройств периферии
  const camStorage = () => (find(CAM)?.n.devices || []).find((d) => d.type === "storage")?.id;
  const sliceBtn = (s) => q(`#aside [data-slice="${s}"]`);
  // Строка дерева: если папка свёрнута, раскрыть путь к строке
  const treeRow = (id) => () => {
    let r = document.querySelector(`#tree .n[data-pick="${id}"]`);
    if (!r && find(id)) { expandTo(id); renderTree(); renderTreeFlush(); r = document.querySelector(`#tree .n[data-pick="${id}"]`); }
    return r;
  };
  const tabBtn = (re) => byText(".hd .tabs .tab", re);
  const modal = () => !!document.querySelector("#bmodal.open");
  const onStorage = () => app === "hw" && find(sel)?.n.type === "storage" && tab === "rep" && !modal();
  const reset = () => { wzDrop("rule"); closeBulkModal(); };

  const steps = [
    { ch: { id: "overview", title: "Все встроенные хранилища сервера", why: "Одна таблица показывает камеры сервера со встроенным хранилищем: как настроена репликация и что с ней сейчас." },
      say: "Встроенное хранилище — это карта памяти камеры или диск регистратора. Все хранилища видны в срезе «Хранилища». Выберем его.",
      before: () => { reset(); goApp("hw"); setSlice("all"); }, at: sliceBtn("arch"), act: "click" },
    { say: "Откроем сервер «Центр/Сервер — Офис».", at: when(() => slice === "arch", treeRow(SRV)), act: "click" },
    { say: "У сервера и у домена есть вкладка «Встроенные хранилища». Откроем её.", at: when(() => sel === SRV, tabBtn(/Встроенные хранилища/)), act: "click" },
    { say: "Вверху написано, у скольких камер есть проблемы. Эти камеры стоят в начале таблицы.", at: when(() => document.querySelector(".eo-tbl"), q(".eo-nt")) },
    { say: "Справка объясняет каждое состояние. Откроем её.", at: q(".eo-legend summary"), act: "click" },
    { say: "Сначала смотрите на состояния «записи потеряны» и «нет связи». То же пояснение показывает подсказка у чипа в таблице.", at: when(() => document.querySelector(".eo-legend[open]"), q(".eo-legend dl")) },
    { say: "Фильтр оставляет только нужные камеры. Выберем камеры без связи.", at: q('#main .bk-scope [data-fk="state:нет связи"]'), act: "click" },
    { say: "В строке видно камеру, способ репликации, состояние и подробности: что случилось и что сервер сделает дальше.", at: when(() => eoSel.f.state, q(".eo-row")) },
    { say: "Вернём все камеры.", at: q('#main .bk-scope [data-fk="all"]'), act: "click" },
    { say: "Нажатие на камеру открывает её встроенное хранилище. Там настраивают репликацию.", at: when(() => !eoSel.f.state, q(".eo-row .er-go")), act: "click" },
    { say: "Это страница встроенного хранилища камеры. Как она устроена, покажет следующая глава.", at: when(onStorage, q("#main .er-types")) },

    { ch: { id: "camera", title: "От камеры к встроенному хранилищу", why: "Встроенное хранилище — часть камеры. Его можно найти и настроить прямо из карточки камеры." },
      say: "Выберем срез «Камеры».", before: () => { reset(); goApp("hw"); setSlice("all"); }, at: sliceBtn("cam"), act: "click" },
    { say: "Откроем камеру «Главный вход».", at: when(() => slice === "cam", treeRow(CAM)), act: "click" },
    { say: "Вкладка «Периферия» показывает всё, что подключено к камере. Откроем её.", at: when(() => sel === CAM, tabBtn(/^Периферия$/)), act: "click" },
    { say: "Здесь датчики, реле, микрофоны и карта памяти. Фильтр оставит только встроенные хранилища.", at: q('#main .bk-scope [data-fk="type:Встроенные хранилища"]'), act: "click" },
    { say: "Камера пишет на карту памяти. Консоль показывает карту как встроенное хранилище. Откроем его.", at: when(() => periphSel.f.type, byText("#main .pf-nm", /хранилище/i)), act: "click" },
    { say: "Вкладка «Репликация» говорит, забирает ли сервер записи с карты. Постоянных вариантов два: «Выключена» и «Забирать всё».", at: when(onStorage, q("#main .er-types")) },
    { say: "«Забирать всё»: камера пишет только на карту, а сервер забирает с карты все записи. Архив отстаёт на несколько минут.", at: byText("#main .er-types .er-t", /Забирать всё/) },
    { say: "Другие способы сервер выполняет по правилам автоматизации. Каждая карточка внизу создаёт такое правило.", at: q("#main .er-rules-add .er-types") },
    { say: "Полоса показывает сутки. Синий цвет показывает, что сервер заберёт с карты. Серый цвет показывает живой поток в архив.", at: byText("#main .er-t-rule", /Заполнять пропуски/) },
    { say: "Если связь с камерой иногда пропадает, подходит «Заполнять пропуски». Нажмём на карточку.", at: byText("#main .er-t-rule", /Заполнять пропуски/), act: "click" },
    { say: "Открылся мастер правила. Консоль сама выбрала шаблон и подставила камеры хранилища.", at: when(modal, q("#bmBody .rl-opt.on")) },
    { say: "Сейчас мы только смотрим. «Отмена» закрывает мастер и возвращает на страницу хранилища.", at: byText("#bmFoot .btn", /^\s*Отмена\s*$/), act: "click" },
    { say: "Мы снова на странице хранилища. Кнопка «Забрать период…» забирает записи за выбранный период один раз, без правила.", at: when(onStorage, byText("#main .btn", /Забрать период/)) },
    { say: "Итог: хранилище камеры находится на вкладке «Периферия». На его странице выбирают постоянную репликацию или создают правило." },

    { ch: { id: "rule", title: "Правило «Заполнять пропуски» в «Автоматизации»", why: "Правило само забирает с карты минуты, которые архив пропустил, пока не было связи." },
      say: "Правило можно создать и в разделе «Автоматизация». Эта кнопка создаёт новое правило.",
      before: () => { reset(); goApp("rules"); }, at: byText("#aside .btn", /^\s*Правило\s*$/), act: "click" },
    { say: "Пропуски забирают, когда связь вернулась, то есть по событию. Оставляем запуск по событию.", at: when(modal, q("#bmodal [data-rnw]")) },
    { say: "Идём к шаблонам.", at: byText("#bmodal .btn", /Далее/), act: "click" },
    { say: "Шаблоны репликации стоят в группе «Репликация со встроенного хранилища».", at: byText("#bmodal .rl-tpl-g", /Репликация со встроенного хранилища/) },
    { say: "Выбираем «Связь вернулась: забрать пропуски с карты».", at: byText("#bmodal .rl-opt", /Связь вернулась: забрать пропуски/), act: "click" },
    { say: "Создаём правило. Консоль создаёт его выключенным: правило не сработает, пока вы его не включите.", at: byText("#bmodal .btn", /Создать правило/), act: "click" },
    { say: "Правило ждёт событие «Камера: связь восстановлена». Осталось выбрать камеру, у которой ждать возврата связи.", at: when(() => !modal(), byText("#main .rl-pick", /Выбрать камеру/)), act: "click" },
    { say: "Находим камеру по названию.", at: q("#rpQ"), act: "type", text: "Главный вход" },
    { say: "Отмечаем камеру.", at: byText("#rpList .rl-pk[data-tok]", /Главный вход/), act: "click" },
    { say: "Подтверждаем выбор.", at: q("#rpOk"), act: "click" },
    { say: "Правило выполняет действие «Начать репликацию». Поле «Что забрать» говорит: пропуски, пока не было связи. Камеру действие берёт из события.",
      at: () => document.querySelector('select[data-ks="0"]')?.closest(".rl-row") },
    { say: "Чтобы сохранить правило, покажем план изменений.", at: byText("#main .card-foot .btn", /Показать план/), act: "click" },
    { say: "План перечисляет, что изменится. Применяем.", at: byText("#bmodal.open .btn", /Применить/), act: "click" },
    { say: "Консоль сохранила правило выключенным. Включите его здесь, когда будете готовы.", at: when(() => !modal() && !ruleDiffLive().length, q(".rl-seg")) },
    { say: "Правило видно и на странице встроенного хранилища камеры. Откроем её.",
      before: () => { goApp("hw"); pick(camStorage(), { tab: "rep" }); }, at: when(onStorage, q("#main .er-rules")) },
    { say: "Итог: общий вид у сервера показывает состояние всех хранилищ, страница хранилища настраивает одну камеру, а правило забирает пропуски само." },
  ];
    return steps;
  })(),
});

Tour.start();
